    });

    test('comments and blank lines do not corrupt tracking', function () {
        var yml = [
            'permissions:',
            '  # the ceiling grant',
            '',
            '  contents: write',
            '  contents: write'
        ].join('\n');
        assert.equal(lint.findDuplicateKeys(yml).length, 1);
    });

