    });

    test('quoted trigger keys are unquoted', function () {
        var yml = 'on:\n  "issues":\n  workflow_dispatch:\njobs: {}';
        assert.deepEqual(lint.extractTriggers(yml), ['issues', 'workflow_dispatch']);
